document.querySelector('.menu-toggle')?.addEventListener('click',event=>{const button=event.currentTarget;const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));document.querySelector('.nav').classList.toggle('open',!expanded);button.textContent=expanded?'Menu':'Close';});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const menu=document.querySelector('.menu-toggle');if(menu?.getAttribute('aria-expanded')==='true'){menu.click();menu.focus();}}});
const filters=[...document.querySelectorAll('[data-filter]')];
filters.forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.filter;filters.forEach(item=>item.setAttribute('aria-pressed',String(item===button)));let count=0;document.querySelectorAll('[data-category]').forEach(card=>{const visible=value==='all'||card.dataset.category===value;card.hidden=!visible;if(visible)count++;});document.querySelector('.filter-result').textContent=`${count} project${count===1?'':'s'}`;}));
document.querySelectorAll('[data-gallery]').forEach(gallery=>{const items=JSON.parse(gallery.dataset.gallery);const main=gallery.querySelector('.gallery-main');const opener=gallery.querySelector('[data-view]');gallery.querySelectorAll('.thumb').forEach((thumb,index)=>thumb.addEventListener('click',()=>{const item=items[index];main.src=`assets/${item.image}`;main.alt=item.alt;opener.dataset.view=main.src;opener.dataset.caption=item.caption;opener.dataset.alt=item.alt;opener.setAttribute('aria-label',`Enlarge image: ${item.alt}`);gallery.querySelector('.gallery-description').textContent=item.caption;gallery.querySelector('.gallery-count').textContent=`${index+1} / ${items.length}`;gallery.querySelectorAll('.thumb').forEach(t=>t.setAttribute('aria-pressed',String(t===thumb)));}));});
const dialog=document.querySelector('.lightbox');
if(dialog){let items=[];let position=0;let returnFocus=null;const img=dialog.querySelector('img');const show=()=>{const item=items[position];img.src=item.src;img.alt=item.alt;dialog.querySelector('.lightbox-caption').textContent=item.caption;dialog.querySelector('.lightbox-counter').textContent=`Image ${position+1} of ${items.length}`;dialog.querySelectorAll('[data-direction]').forEach(b=>b.hidden=items.length<2);};document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{returnFocus=button;const gallery=button.closest('[data-gallery]');if(gallery){items=JSON.parse(gallery.dataset.gallery).map(x=>({src:`assets/${x.image}`,alt:x.alt,caption:x.caption}));position=Math.max(0,items.findIndex(x=>button.dataset.view.endsWith(x.src)));}else{items=[...document.querySelectorAll('[data-view]')].filter(x=>!x.closest('[data-gallery]')).map(x=>({src:x.dataset.view,alt:x.dataset.alt,caption:x.dataset.caption}));position=Math.max(0,items.findIndex(x=>x.src===button.dataset.view));}show();dialog.showModal();dialog.querySelector('[data-close]').focus();}));dialog.querySelector('[data-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>returnFocus?.focus());const move=direction=>{position=(position+direction+items.length)%items.length;show();};dialog.querySelectorAll('[data-direction]').forEach(button=>button.addEventListener('click',()=>move(Number(button.dataset.direction))));dialog.addEventListener('keydown',event=>{if(event.key==='ArrowRight'){event.preventDefault();move(1);}if(event.key==='ArrowLeft'){event.preventDefault();move(-1);}});dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});}
document.querySelector('[data-copy-email]')?.addEventListener('click',async event=>{const email=event.currentTarget.dataset.copyEmail;const status=document.querySelector('.copy-status');try{await navigator.clipboard.writeText(email);status.textContent='Email address copied.';}catch{status.textContent='Email: '+email;}});
